\draw[->,dashed,color={rgb,255:red,38;green,140;blue,255}] (0,0)--(2.5,0)--(2.5,3.5);
\draw[->,dashed,color={rgb,255:red,239;green,96;blue,104}] (0,0)--(4,0)--(4,1.5);
